import{_ as n,l,o as e,c as i,v as r,p as s,x as o,d,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Longformer 稀疏注意模式","description":"","frontmatter":{"title":"Longformer 稀疏注意模式","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/longformer-pattern.md","filePath":"llm/longformer-pattern.md","lastUpdated":1789023840000}'),p={name:"llm/longformer-pattern.md"};function f(c,a,g,E,u,B){const t=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="longformer-稀疏注意模式" tabindex="-1">Longformer 稀疏注意模式 <a class="header-anchor" href="#longformer-稀疏注意模式" aria-label="Permalink to &quot;Longformer 稀疏注意模式&quot;">​</a></h1><div class="epigraph"><p>每一层以滑窗为底盘，部分头做膨胀以扩大感受野；再只给任务指定的少数标记开全局通道。边集是设计出来的，不是学出来的。</p><footer>—— Beltagy, Peters &amp; Cohan, Longformer: The Long-Document Transformer，arXiv:2004.05150，2020</footer></div><p>Beltagy、Peters 与 Cohan 的 Longformer 要把预训练编码器从 512 词接到几千词的文档，关键不是新的打分函数，而是<strong>注意力图的边集</strong>。满注意力的 \\(n\\times n\\) 在文档长度上先爆显存；稀疏之后，谁看见谁必须写清楚，否则层叠的窗会留下盲区，任务需要的全局读又会被窗切断。本篇按原文把三种模式——滑窗、膨胀窗、全局点——如何拼成一张线性复杂度的图写完。任务驱动的续训与 LED 见 <a href="/llm/longformer">Longformer</a>；图论对照见 <a href="/llm/sparse-attention-patterns">稀疏模式</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自注意力默认是完全图：位置 \\(i\\) 对 \\(1\\ldots n\\) 都有一条边。文档级 \\(n\\) 到 4K，分数矩阵与中间激活按 \\(n^2\\) 走，当时的 BERT/RoBERTa 只能截断。截断把答案留在窗外；滑窗集成没有层内的远程边，跨段指代要靠启发式。需要一张图，使：(1) 相邻 token 始终互相可见，以继承已经学好的短程句法；(2) 深度方向上感受野能覆盖整篇；(3) 分类符或问句这类「必须读全文」的位置有度数 \\(\\Theta(n)\\) 的通道；(4) 每层边数对 \\(n\\) 线性，以便自定义核不必物化掩码矩阵。</p><p>边不能全靠内容学习——那会回到另一套动态 gather，2020 年的编码器续训也没有这条预算。Longformer 的选择是<strong>确定稀疏</strong>：窗宽、膨胀、全局位置都是超参与任务标注，训练只学投影权重，不学边。</p><h3 id="感受野必须随层扩张-而不能指望单层满连接" tabindex="-1">感受野必须随层扩张，而不能指望单层满连接 <a class="header-anchor" href="#感受野必须随层扩张-而不能指望单层满连接" aria-label="Permalink to &quot;感受野必须随层扩张，而不能指望单层满连接&quot;">​</a></h3><p>一层宽度 \\(w\\) 的对称窗，每个位置只看见半径 \\(w/2\\)。堆 \\(L\\) 层，理论感受野约为 \\(L\\cdot w\\)（不计膨胀）。\\(w=512\\)、\\(L=12\\) 时已经可以跨过数千 token，前提是信息真能沿残差逐层传，而不是在某一层被局部噪声盖住。单层满连接没有这个问题，但也没有线性代价。膨胀把同一边数铺到更大半径，代价是隔掉的位置在该头上不可见，必须靠其它头或其它层补。</p><p><span class="marginnote">确定图与内容稀疏（Routing、LSH）的分工在这里就要划清：Longformer 不根据点积选边，问句之所以看见全文，是因为任务把那些位置标成了全局。换任务就要改标注，图不是模型自己发现的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="滑窗" tabindex="-1">滑窗 <a class="header-anchor" href="#滑窗" aria-label="Permalink to &quot;滑窗&quot;">​</a></h3><p>设窗宽为 \\(w\\)（偶数便于两侧对称）。编码器设定下，位置 \\(i\\) 的可见集是 \\(\\{i-w/2,\\ldots,i+w/2\\}\\) 与序列边界的交。因果语言模型则只保留过去一侧。复杂度每层 \\(O(nwd)\\)。窗是底盘：所有层、所有头至少拥有这组局部边，避免表示变成袋模型。实现上不能先形成 \\(n\\times n\\) 再掩码——那只是把零乘得很快，显存仍按平方走。原文用自定义 CUDA 按带状模式计算，这是线性宣称成立的条件。</p><h3 id="膨胀窗" tabindex="-1">膨胀窗 <a class="header-anchor" href="#膨胀窗" aria-label="Permalink to &quot;膨胀窗&quot;">​</a></h3><p>膨胀窗在窗内插入空隙：可见位置变成 \\(i\\pm 1, i\\pm(1+d), i\\pm(1+2d),\\ldots\\)，直到大约 \\(w\\) 条边用完。同一层的不同头可以取不同 \\(d\\)，有的头密看近邻，有的头稀看更远。这直接借自膨胀卷积：边数不变，理论半径变大。空隙中的 token 在该头上不相邻，依赖其它头的密窗或全局点中转。原文把膨胀主要用于深层，浅层保持密窗，以免一开始就把局部句法拆碎。</p><h3 id="全局点" tabindex="-1">全局点 <a class="header-anchor" href="#全局点" aria-label="Permalink to &quot;全局点&quot;">​</a></h3><p>少量位置 \\(g_1,\\ldots,g_G\\) 被标成全局：每个 \\(g\\) 看见全体位置，全体位置也看见每个 \\(g\\)。边数增加 \\(O(Gn)\\)，只要 \\(G\\) 视为常数（CLS、问句 token、若干分隔符），总复杂度仍线性。分类任务通常只标 CLS；抽取式 QA 把问题侧全部标全局，使每个文档 token 都能直接读到问句，问句也能汇聚全文。全局点是<strong>对称双向</strong>的：不只是「CLS 读大家」，也包括「大家写 CLS」。少了后一半，全局通道就只是汇聚、不是广播。</p>',16)),(e(),s(h,null,{default:o(()=>[m(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E6%BB%91%E7%AA%97%20%E5%AE%BD%20w%22%5D%20--%3E%20U%5B%22%E8%BE%B9%E9%9B%86%E5%90%88%E5%B9%B6%22%5D%0A%20%20D%5B%22%E8%86%A8%E8%83%80%E7%AA%97%20%E9%83%A8%E5%88%86%E5%A4%B4%22%5D%20--%3E%20U%0A%20%20G%5B%22%E4%BB%BB%E5%8A%A1%E5%85%A8%E5%B1%80%E7%82%B9%22%5D%20--%3E%20U%0A%20%20U%20--%3E%20A%5B%22%E7%A8%80%E7%96%8F%20softmax%22%5D%0A%20%20A%20--%3E%20Y%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>三种模式在图上取并：位置 \\(i\\) 的可见集是窗（或膨胀窗）并上全部全局点；若 \\(i\\) 本身是全局点，可见集是全体。softmax 仍在各自的可见集上做，打分函数还是缩放点积，没有改核。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>滑窗提供局部全连接，信息沿深度做扩散：第 \\(\\ell\\) 层的有效上下文大约是半径 \\(\\ell w/2\\) 的金字塔。膨胀加速扩散，类似卷积里的空洞：同一深度可以跨过更远，但金字塔变得有孔。全局点把直径压到常数级——任意两点至多两跳，经由某个全局枢纽。这解释了为何 QA 必须把问句设为全局：否则问题与远离窗的证据只有经多层扩散才能相遇，而扩散在有损残差里不保证送达。</p><h3 id="任务图与预训练图不是同一张" tabindex="-1">任务图与预训练图不是同一张 <a class="header-anchor" href="#任务图与预训练图不是同一张" aria-label="Permalink to &quot;任务图与预训练图不是同一张&quot;">​</a></h3><p>继续 MLM 时，图往往只有 CLS 一类少量全局点，窗宽扩到目标长度所需的局部覆盖。下游微调把问句标成全局，图的度数突变。模型要在微调里学会「这些新的度数为 \\(n\\) 的通道」。若微调数据少、全局点又多，优化会把质量堆到全局通道上、局部窗被架空，或反过来从不使用全局边。原文用任务格式保证全局点在输入里语义明确（这是问句、这是 CLS），而不是让模型从随机位置里找枢纽。</p><p><span class="marginnote">LED 把同一套编码器稀疏图接到解码器上做长摘要。解码器自注意力仍可是因果满注意力（输出通常短）；交叉注意力的源长度等于编码器输出长度。编码器稀疏不等于交叉免费，但源侧可以先被线性图吃下。不要把 LED 写成「编解码两侧都线性且对称」。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>确定稀疏的代价是图与任务绑定。核心ference、摘要、分类、QA 的全局位置不同；做成通用解码器 LM 时，「哪些 token 该全局」没有自然答案——不能把每个生成步的当前 token 都标全局，那会回到平方。这也是 Longformer 停在编码器主场、而不是直接成为 GPT 类层规范的原因。膨胀在语言上不如在视觉卷积里直观：token 网格没有像素那种平移等变，过大的 \\(d\\) 会切开短语。</p><p>窗宽 \\(w\\) 是显存与局部质量的旋钮。\\(w\\) 取 512 时，单层局部能力与 BERT 相当，线性项的常数很大；\\(w\\) 取太小，即使堆层，浅层句法也会伤。自定义核的实现细节决定「线性」是真是假：PyTorch 稠密加掩码在 2020 年就能训一个「逻辑上稀疏」的模型，却训不出论文宣称的长度。复现必须核与图一致。随机边不在原文图里；那是 <a href="/llm/bigbird-theory">BigBird</a> 为直径与理论完备性另加的一类边。把 Longformer 写成「窗加随机加全局」，是把两篇论文的图并成一张。</p><p><span class="marginnote">位置嵌入仍是绝对表。图改成 4K 之后，512 行的 RoBERTa 位置表要外插或复制。稀疏模式不自动解决长度外推：它只解决「4K 上算得动」。外推是另一条线（ALiBi、RoPE、YaRN）。</span></p><h3 id="与满注意力可视化的差别" tabindex="-1">与满注意力可视化的差别 <a class="header-anchor" href="#与满注意力可视化的差别" aria-label="Permalink to &quot;与满注意力可视化的差别&quot;">​</a></h3><p>稀疏图上的注意力权重不能按稠密热图来读。窗外是结构零，不是分数低。全局点行与列会吸走大量质量，看起来像「模型只看 CLS」，其实是图强迫的枢纽交通。分析头功能时应把强制边与学到的窗内尖峰分开；否则会把任务标注误认成涌现出的全局头。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Longformer 的稀疏模式是滑窗底盘、可选膨胀、任务指定的全局点三者取并。</li><li>复杂度 \\(O(nwd+Gnd)\\)；\\(G\\) 当常数时对 \\(n\\) 线性，前提是不物化 \\(n\\times n\\)。</li><li>全局点对称：枢纽读全体，全体也写枢纽；QA 标问句，分类标 CLS。</li><li>边集确定、不按内容选边；换任务就要改哪些位置是全局。</li><li>感受野靠深度与膨胀扩张；单层仍是局部的，除非该位置被标全局。</li><li>出处：Beltagy, Peters &amp; Cohan，<em>Longformer: The Long-Document Transformer</em>，arXiv:2004.05150，2020。</li></ul>',14))])}const A=n(p,[["render",f]]);export{_ as __pageData,A as default};
